'use strict';
let effectsEnabled=localStorage.getItem('starlight-effects')!=='off',effectsContext;
function playEffect(kind='click'){if(!effectsEnabled)return;try{effectsContext??=new (window.AudioContext||window.webkitAudioContext)();effectsContext.resume();const notes=kind==='hit'?[180,90]:kind==='start'?[392,523,659]:kind==='finish'?[523,659,784,1047]:[740,988];notes.forEach((frequency,i)=>{const o=effectsContext.createOscillator(),g=effectsContext.createGain(),t=effectsContext.currentTime+i*.065;o.type='sine';o.frequency.setValueAtTime(frequency,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.065,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+.11);o.connect(g);g.connect(effectsContext.destination);o.start(t);o.stop(t+.12)})}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.effects!==undefined){effectsEnabled=!effectsEnabled;localStorage.setItem('starlight-effects',effectsEnabled?'on':'off');document.querySelectorAll('[data-effects]').forEach(v=>{v.textContent=effectsEnabled?'音效：開':'音效：關';v.setAttribute('aria-pressed',String(effectsEnabled))});if(effectsEnabled)playEffect();return}playEffect(b.dataset.quest?'start':'click')},true);
document.addEventListener('keydown',e=>{if(page==='landing'&&!e.repeat&&!['Tab','Shift','Control','Alt','Meta'].includes(e.key))playEffect('start')},true);
const adventureSoundButton=soundButton;soundButton=function(){return adventureSoundButton()+`<button class="nav-pill" data-effects aria-pressed="${effectsEnabled}">音效：${effectsEnabled?'開':'關'}</button>`};
let bgmEnabled=localStorage.getItem('starlight-bgm')!=='off',bgmContext,bgmTimer,bgmVoices=[],bgmStep=0,bgmSignature='';
const bgmThemes={
 forest:[60,64,67,71,74,71,67,64],peaks:[62,66,69,74,78,74,69,66],ruins:[57,60,64,67,69,67,64,60],castle:[55,59,62,67,71,67,62,59],valley:[65,69,72,76,77,76,72,69],port:[62,65,69,72,74,72,69,65],coast:[60,64,67,72,74,72,67,64]};
const weatherOffsets={sunny:0,rain:-5,dusk:-2,night:-12,snow:2};
function stopJourneyMusic(){clearInterval(bgmTimer);bgmTimer=null;bgmVoices.forEach(v=>{try{v.stop()}catch{}});bgmVoices=[];bgmSignature=''}
function toneHz(midi){return 440*Math.pow(2,(midi-69)/12)}
function playJourneyTone(midi,when,duration,volume=.028){if(!bgmContext)return;const osc=bgmContext.createOscillator(),gain=bgmContext.createGain();osc.type='triangle';osc.frequency.setValueAtTime(toneHz(midi),when);gain.gain.setValueAtTime(.0001,when);gain.gain.exponentialRampToValueAtTime(volume,when+.04);gain.gain.exponentialRampToValueAtTime(.0001,when+duration);osc.connect(gain);gain.connect(bgmContext.destination);osc.start(when);osc.stop(when+duration+.03);bgmVoices.push(osc)}
function startJourneyMusic(journey){if(!bgmEnabled||!timer?.running)return;const signature=`${journey.region}-${journey.sceneKey}`;if(bgmSignature===signature&&bgmTimer)return;stopJourneyMusic();try{bgmContext??=new (window.AudioContext||window.webkitAudioContext)();bgmContext.resume();bgmSignature=signature;bgmStep=0;const notes=bgmThemes[journey.region]||bgmThemes.forest,offset=weatherOffsets[journey.sceneKey]||0;const pulse=()=>{if(!timer?.running||!bgmEnabled||!$('#expedition')){stopJourneyMusic();return;}const now=bgmContext.currentTime+.02,note=notes[bgmStep%notes.length]+offset;playJourneyTone(note,now,.42,.024);if(bgmStep%2===0)playJourneyTone(note-12,now,.25,.012);if(journey.sceneKey==='rain'&&bgmStep%4===1)playJourneyTone(note+7,now,.18,.01);bgmStep++};pulse();bgmTimer=setInterval(pulse,480)}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-bgm]');if(!b)return;bgmEnabled=!bgmEnabled;localStorage.setItem('starlight-bgm',bgmEnabled?'on':'off');document.querySelectorAll('[data-bgm]').forEach(v=>{v.textContent=`旅程音樂：${bgmEnabled?'開':'關'}`;v.setAttribute('aria-pressed',String(bgmEnabled))});if(!bgmEnabled)stopJourneyMusic();else if(timer){const q=data.quests.find(q=>q.id===timer.id);if(q)startJourneyMusic(missionJourney(q))}},true);
const expeditionPlaces={forest:{name:'霧語黑森林',asset:'forest',monster:'森林史萊姆',color:'#8ec6aa'},peaks:{name:'雲頂觀星台',asset:'valley',monster:'琥珀小石怪',color:'#dba66c'},ruins:{name:'古鐘地城',asset:'castle',monster:'古鐘石像',color:'#b6a0d2'},castle:{name:'星晶城堡',asset:'castle',monster:'星光小幽靈',color:'#b6a0d2'},valley:{name:'月泉小村',asset:'valley',monster:'書頁精靈',color:'#dba66c'},port:{name:'曦光港市集',asset:'coast',monster:'海風精靈',color:'#87b9d4'},coast:{name:'風燈海岸',asset:'coast',monster:'水滴精靈',color:'#87b9d4'}};
const journeyScenes={sunny:{label:'晴朗 · 微風吹拂',weather:'sunny',time:'day'},rain:{label:'細雨 · 滴答滴答',weather:'rain',time:'day'},dusk:{label:'黃昏 · 金色餘暉',weather:'sunny',time:'dusk'},night:{label:'月夜 · 星光閃閃',weather:'night',time:'night'},snow:{label:'飄雪 · 奇幻冬日',weather:'snow',time:'day'}};
function missionJourney(q){const region=typeof placeForQuest==='function'?placeForQuest(q):'forest';const place=expeditionPlaces[region]||expeditionPlaces.forest;const options=Object.keys(journeyScenes);const auto=options[Math.abs(String(q.id||q.title||'').split('').reduce((n,c)=>n+c.charCodeAt(0),0))%options.length];const sceneKey=q.scene==='auto'||!journeyScenes[q.scene]?auto:q.scene;const scene=journeyScenes[sceneKey];return {region,place,scene,sceneKey}}
function paintJourney(stage,q){const journey=missionJourney(q);stage.style.setProperty('--painted-scene',`url('assets/journey-${journey.region}-${journey.sceneKey}.png'), url('assets/journey-${journey.place.asset}.png')`);stage.querySelector('.exp-enemy-art').style.backgroundPosition=journey.place.asset==='forest'?'0 0':journey.place.asset==='coast'?'0 100%':journey.place.asset==='castle'?'100% 100%':'100% 0';stage.style.setProperty('--monster-color',journey.place.color);stage.dataset.weather=journey.scene.weather;stage.dataset.time=journey.scene.time;$('#exp-location').textContent=journey.place.name;$('#exp-weather-name').textContent=journey.scene.label;$('#exp-monster-name').textContent=journey.place.monster;return `${journey.place.name}-${journey.scene.weather}-${journey.scene.time}`}
function adventureStage(){return `<div class="expedition" id="expedition" role="img" aria-label="勇者在橫向冒險世界行走"><div class="exp-sun"></div><div class="exp-clouds"></div><div class="exp-far"></div><div class="exp-near"></div><div class="exp-ground"></div><div class="exp-weather"></div><div class="exp-title"><span>FOCUS JOURNEY</span><strong id="exp-location">翠葉森林</strong><small id="exp-weather-name">晴朗</small></div><div class="exp-hero" style="background-position:${(data.hero%3)*50}% ${Math.floor(data.hero/3)*100}%"></div><div class="exp-monster"><div class="exp-enemy-art"></div><span id="exp-monster-name">森林史萊姆</span></div><div class="exp-strike" aria-hidden="true"></div><div class="exp-battle-note" id="exp-battle-note" aria-live="off"></div><div class="exp-distance" id="exp-distance">旅程開始</div></div><div class="exp-progress"><span id="exp-progress-bar"></span></div>`}
drawTimer=function(){const q=data.quests.find(q=>q.id===timer.id);openModal('timer',`<div class="timer-panel expedition-panel"><p class="subtle">${esc(q.detail)}</p>${adventureStage()}<div class="timer-number" id="timer-clock">${formatTime(timer.total-elapsed())}</div><p class="subtle" id="timer-note">準備好課本，勇者會陪住你一路前進。</p><div class="inline-actions" style="margin-top:20px"><button class="primary" data-action="pause" id="pause-btn">暫停休息</button><button class="ghost" data-action="save-timer">儲存並返回</button><button class="ghost" data-bgm aria-pressed="${bgmEnabled}">旅程音樂：${bgmEnabled?'開':'關'}</button><button class="ghost" data-effects aria-pressed="${effectsEnabled}">音效：${effectsEnabled?'開':'關'}</button></div><div id="timer-finish"></div></div>`,'專注冒險 · '+q.title);$('.modal').classList.add('expedition-modal');timer.lastJourney='';timer.finishedSound=false;tickTimer()};
tickTimer=function(){if(!timer||!$('#timer-clock'))return;const e=elapsed(),stage=$('#expedition'),q=data.quests.find(q=>q.id===timer.id);$('#timer-clock').textContent=formatTime(timer.total-e);if(stage){stage.classList.toggle('is-paused',!timer.running);if(!timer.running)stopJourneyMusic();const key=paintJourney(stage,q);timer.lastJourney=key;startJourneyMusic(missionJourney(q));updateEncounter(stage,e,timer.running);$('#exp-distance').textContent=`旅程 ${Math.floor(e/60)} 分 ${Math.floor(e%60)} 秒 · ${Math.min(100,Math.floor(e/timer.total*100))}%`;$('#exp-progress-bar').style.width=Math.min(100,e/timer.total*100)+'%'}if(e>=timer.total){timer.acc=timer.total;timer.running=false;clearInterval(timer.handle);stopJourneyMusic();stage?.classList.add('is-paused');$('#pause-btn').disabled=true;$('#timer-note').textContent='旅程完成！記錄一下今次嘅努力。';if(!timer.finishedSound){playEffect('finish');timer.finishedSound=true}$('#timer-finish').innerHTML=`<p class="subtle" style="margin:20px 0 12px">今次完成咗幾多？</p><div class="inline-actions"><button class="primary small-btn" data-finish="complete">已完成任務</button><button class="ghost small-btn" data-finish="partial">做咗一部分</button><button class="ghost small-btn" data-finish="help">有啲地方唔明</button></div>`}};
function encounterState(seconds){const t=seconds%20;return {phase:t<7?'approach':t<10?'attack':t<13?'defeated':'travel',x:t<7?105-t/7*65:40,strike:Math.floor((t-7)*2)}}
function updateEncounter(stage,seconds,running){const state=encounterState(seconds);stage.dataset.encounter=state.phase;stage.style.setProperty('--enemy-x',state.x+'%');stage.style.setProperty('--attack-sway',state.strike%2?'1':'-1');const note=$('#exp-battle-note');if(note)note.textContent=state.phase==='attack'?'勇者出招！':state.phase==='defeated'?'擊退怪物，繼續前進！':'';if(state.phase==='attack'&&running&&timer.lastStrike!==Math.floor(seconds*2)){timer.lastStrike=Math.floor(seconds*2);playEffect('hit')}}
render();

// The timer ends in a victory scene; rewards become pending until the parent approves them.
const priorReviewScoreCheck=readReviewScore;
readReviewScore=function(q){return q?.completionEvidence==='timer'?true:priorReviewScoreCheck(q)};
function victoryRewardPreview(q){const crystals=q.baseCrystals??Math.round(q.xp/2),m=q.materials||{wood:0,stone:0,metal:0};const materials=Object.values(m).some(Boolean)?`<span>🪵 ${m.wood||0} 木材</span><span>🪨 ${m.stone||0} 石材</span><span>⚙️ ${m.metal||0} 金屬</span>`:'';return `<div class="victory-rewards"><span>✦ +${q.xp} EXP</span><span>◆ +${crystals} 水晶</span>${materials}</div>`}
function finishTimerVictory(q,stage){if(timer.victoryShown)return;timer.victoryShown=true;stage.dataset.encounter='victory';stage.classList.add('victory-state');try{paintHeroSprite(stage.querySelector('.exp-hero'),data.hero||0,'win')}catch{};$('#timer-note').textContent='勝利！你完成咗今次專注旅程。';$('#timer-finish').innerHTML=`<section class="victory-card"><p class="victory-kicker">QUEST COMPLETE</p><h3>任務完成！</h3><p>勇者已把成果交到公會長手上。</p>${victoryRewardPreview(q)}<small>以上獎勵等待家長確認後，才會正式加入你的冒險紀錄。</small><button class="primary" data-victory-ok="${q.id}">OK · 返小屋 ${icon('home')}</button></section>`}
const timerVictoryTick=tickTimer;
tickTimer=function(){timerVictoryTick();if(!timer||timer.victoryShown||elapsed()<timer.total)return;const q=data.quests.find(v=>v.id===timer.id),stage=$('#expedition');if(q&&stage)finishTimerVictory(q,stage)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-victory-ok]');if(!b||!timer)return;const q=data.quests.find(v=>v.id===b.dataset.victoryOk);if(!q)return;clearInterval(timer.handle);timer=null;data.timerDraft=null;q.status='review';q.completionEvidence='timer';q.completedAt=new Date().toISOString();data.totalMinutes+=q.minutes;logActivity('submit',q.title,'專注旅程完成 · 等待公會長確認獎勵');persist();render();go('room');notify('任務已交到公會長手上，獎勵等待確認。')},true);
